import string

def encode_cyclic(s: str) -> str:
    """
    Returns encoded string by cycling groups of three characters.
    """
    # Split the string into groups of up to 3 characters
    groups = [s[(i * 3): min((i + 1) * 3, len(s))] for i in range((len(s) + 2) // 3)]
    # For each group of 3, rotate right (last char to front)
    encoded_groups = []
    for group in groups:
        if len(group) == 3:
            encoded_groups.append(group[1:] + group[0])
        else:
            encoded_groups.append(group)
    return ''.join(encoded_groups)

def decode_cyclic(s: str) -> str:
    """
    Decodes a string that was encoded with encode_cyclic.
    """
    # Each group of 3 was rotated right; to decode, rotate left (first char to end)
    groups = [s[(i * 3): min((i + 1) * 3, len(s))] for i in range((len(s) + 2) // 3)]
    decoded_groups = []
    for group in groups:
        if len(group) == 3:
            # undo a right rotate by doing a left rotate
            decoded_groups.append(group[1] + group[0] + group[2])
        else:
            decoded_groups.append(group)
    return ''.join(decoded_groups)
