from functools import lru_cache

def fibfib(n: int):
    """
    Compute the n-th FibFib number.
    The FibFib sequence is defined as:
        fibfib(0) = 0
        fibfib(1) = 0
        fibfib(2) = 1
        fibfib(n) = fibfib(n-1) + fibfib(n-2) + fibfib(n-3) for n > 2
    """
    @lru_cache(maxsize=None)
    def helper(k):
        if k == 0:
            return 0
        if k == 1:
            return 0
        if k == 2:
            return 1
        return helper(k - 1) + helper(k - 2) + helper(k - 3)

    return helper(n)
