    if ' ' in txt:
        return txt.split()
    # If no spaces, check for commas
    elif ',' in txt:
        return txt.split(',')
    # No spaces or commas: count lowercase letters with odd alphabetical order (ord 1,3,5,...,25 => a=0 so odd意味着字母在奇数位置)
